import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    ones=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    sixes=[(r,c) for r in range(h) for c in range(w) if g[r][c]==6]
    def line_cells(a,b):
        dr,dc=b[0]-a[0],b[1]-a[1]
        if dr==0: return [(a[0],c) for c in range(min(a[1],b[1]),max(a[1],b[1])+1)]
        if dc==0: return [(r,a[1]) for r in range(min(a[0],b[0]),max(a[0],b[0])+1)]
        from math import gcd
        if abs(dr)%gcd(abs(dr),abs(dc)) or abs(dc)%gcd(abs(dr),abs(dc)): return None
        s=gcd(abs(dr),abs(dc)); step_r,step_c=dr//s,dc//s
        return [(a[0]+step_r*i,a[1]+step_c*i) for i in range(s+1)]
    # pair each 1 with the aligned 1 it forms a straight segment with (demo: unique pairing)
    import itertools
    segs=[]
    for a,b in itertools.combinations(ones,2):
        lc=line_cells(a,b)
        if lc: segs.append(lc)
    # use pairing that covers all ones if possible; here just take segments from aligned pairs
    for lc in segs:
        for r,c in lc:
            if out[r][c]==0 or out[r][c]==4 or out[r][c]==5 or out[r][c]==8:
                pass
        # fill with 1s, keep 6s
        for r,c in lc:
            if out[r][c]!=6: out[r][c]=1
        for sr,sc in sixes:
            if (sr,sc) in lc:
                # perpendicular full line
                if len(lc)>=2 and lc[0][0]==lc[-1][0] or lc[0][1]==lc[-1][1]:
                    # segment horizontal or vertical -> perpendicular vertical/horizontal
                    if lc[0][0]==lc[-1][0]:
                        for r in range(h): out[r][sc]=6
                    else:
                        for c in range(w): out[sr][c]=6
                else:
                    dr=lc[1][0]-lc[0][0]; dc=lc[1][1]-lc[0][1]
                    if dr==dc: # main diag -> anti
                        for r in range(h):
                            c=(sr+sc)-r
                            if 0<=c<w: out[r][c]=6
                    else:
                        for r in range(h):
                            c=sr-sc+r
                            if 0<=c<w: out[r][c]=6
    return out

